import { readFileSync } from ''fs'';
const envContent = readFileSync\(''.env.local'', ''utf-8''\);
for \(const line of envContent.split\(''\\n''\)\) {
  const match = line.match\(/^\([^#=]+\)=\(.*\)$/\);
  if \(match\) process.env[match[1].trim\(\)] = match[2].trim\(\);
}

const { UTApi } = await import\(''uploadthing/server''\);
const utapi = new UTApi\(\);
const files = await utapi.listFiles\({ limit: 50 }\);
console.log\(''Files in UploadThing:'', files.files.length\);
files.files.forEach\(f => console.log\(''  key:'', f.key, ''| name:'', f.name, ''| customId:'', f.customId || ''none''\)\);

if \(files.files.length > 0\) {
  const keys = files.files.map\(f => f.key\);
  console.log\(''\\nDeleting all'', keys.length, ''orphaned files...''\);
  await utapi.deleteFiles\(keys\);
  console.log\(''Done! All garbage cleaned.''\);
}
")
